import { cn } from './cn';

export interface SegmentedProps<T extends string> {
  options: readonly T[];
  value: T;
  onChange: (value: T) => void;
  className?: string;
}

/** Grupo de opções exclusivas em um único controle (ex.: Hoje / 7 dias / 30 dias). */
export function Segmented<T extends string>({ options, value, onChange, className }: SegmentedProps<T>) {
  return (
    <div className={cn('flex rounded-ds border border-line2 bg-surface p-0.5', className)}>
      {options.map((opt) => (
        <button
          key={opt}
          type="button"
          onClick={() => onChange(opt)}
          className={cn(
            'rounded-[4px] px-2.5 py-1 text-base font-medium text-tx3 transition-colors',
            opt === value && 'bg-bg text-tx',
          )}
        >
          {opt}
        </button>
      ))}
    </div>
  );
}
